control.loader_patch:
diff --git a/src/models/qwen/hip/model_loader.cpp b/src/models/qwen/hip/model_loader.cpp
index f4bf772..d0c69c5 100644
--- a/src/models/qwen/hip/model_loader.cpp
+++ b/src/models/qwen/hip/model_loader.cpp
@@ -24,6 +24,8 @@ void ReleaseWeightRegions(std::vector<QwenGpuWeightRegion>& regions) noexcept {
     if (region.host_copy != nullptr) {
       (void)hipHostUnregister(region.host_copy);
       (void)munmap(region.host_copy, region.size);
+    } else if (region.device_data != nullptr) {
+      (void)hipFree(region.device_data);
     }
     region = {};
   }
@@ -68,6 +70,22 @@ void CopyMappedWeights(const core::GgufMappedRegion& source, void* copy) {

 [[nodiscard]] hipError_t MapRegisteredRegion(
     const core::GgufMappedRegion& source, QwenGpuWeightRegion& destination) {
+#if defined(_WIN32)
+  void* device = nullptr;
+  auto status = hipMalloc(&device, source.size);
+  if (status != hipSuccess)
+    return status;
+  status = hipMemcpy(device, source.data, source.size, hipMemcpyHostToDevice);
+  if (status != hipSuccess) {
+    (void)hipFree(device);
+    return status;
+  }
+  destination = {.host_data = source.data,
+                 .device_data = device,
+                 .host_copy = nullptr,
+                 .size = source.size};
+  return hipSuccess;
+#else
   void* host_copy = mmap(nullptr, source.size, PROT_READ | PROT_WRITE,
                          MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
   if (host_copy == MAP_FAILED)
@@ -94,6 +112,7 @@ void CopyMappedWeights(const core::GgufMappedRegion& source, void* copy) {
                  .host_copy = owned_copy.release(),
                  .size = source.size};
   return hipSuccess;
+#endif
 }

